"""Durable fixed steps. Successful outputs are not regenerated by retries."""

import asyncio
import hashlib
import json
from collections.abc import AsyncIterator
from datetime import UTC, datetime
from html import escape
from ipaddress import ip_address
from typing import Any
from urllib.parse import urlsplit
from uuid import uuid4

from ..db import attachments
from ..db.core import Store
from ..errors import AppError
from ..images.jobs import Images
from ..providers.base import ChatRequest, Finish, ProviderMessage, TextDelta
from ..runs.manager import RunManager
from ..schemas import ImageCreate, ImageJob
from ..transcribe.cleanup import Cleanups
from ..transcribe.jobs import TranscriptionManager
from . import templates
from .schemas import WorkflowCreate, WorkflowResume, WorkflowRun, WorkflowStep
from .source import timestamped

ACTIVE = {"queued", "running", "cancelling"}


def now() -> str:
    return datetime.now(UTC).isoformat()


class Workflows:
    def __init__(
        self,
        store: Store,
        runs: RunManager,
        images: Images,
        transcription: TranscriptionManager,
        cleanup: Cleanups,
    ) -> None:
        self.store, self.runs, self.images = store, runs, images
        self.transcription, self.cleanup = transcription, cleanup
        self.lock = asyncio.Lock()
        self.changed = asyncio.Condition()
        self.tasks: dict[str, asyncio.Task[None]] = {}
        self.owned_images: dict[str, str] = {}
        self.owned_cleanup: dict[str, Any] = {}
        self.closing = False

    async def get(self, identifier: str) -> WorkflowRun:
        row = await self.store.one("SELECT * FROM workflow_runs WHERE id=?", (identifier,))
        if not row:
            raise AppError("not_found", "Workflow not found.", 404)
        steps = await self.store.rows(
            "SELECT * FROM workflow_steps WHERE run_id=? ORDER BY position", (identifier,)
        )
        return WorkflowRun(
            id=identifier,
            version=row["version"],
            input=WorkflowCreate.model_validate_json(row["input_json"]),
            state=row["state"],
            stage=row["stage"],
            error=row["error"],
            source_available=row["source_json"] is not None,
            edited_prompt=row["edited_prompt"],
            created_at=row["created_at"],
            updated_at=row["updated_at"],
            steps=[
                WorkflowStep(
                    position=s["position"],
                    kind=s["kind"],
                    label=s["label"],
                    state=s["state"],
                    attempt=s["attempt"],
                    error=s["error"],
                    output=json.loads(s["output_json"]) if s["output_json"] else None,
                )
                for s in steps
            ],
        )

    async def list(self) -> list[WorkflowRun]:
        return [
            await self.get(r["id"])
            for r in await self.store.rows(
                "SELECT id FROM workflow_runs ORDER BY created_at DESC LIMIT 50"
            )
        ]

    async def emit(self, identifier: str) -> None:
        async with self.changed:
            run = await self.get(identifier)
            await self.store.batch(
                [
                    (
                        "INSERT INTO workflow_events(run_id,data_json) VALUES(?,?)",
                        (identifier, run.model_dump_json()),
                    ),
                    (
                        "DELETE FROM workflow_events WHERE id <= "
                        "(SELECT COALESCE(MAX(id),0)-1000 FROM workflow_events)",
                        (),
                    ),
                ]
            )
            self.changed.notify_all()

    async def state(
        self, identifier: str, state: str, stage: str, error: str | None = None
    ) -> None:
        await self.store.execute(
            "UPDATE workflow_runs SET state=?,stage=?,error=?,updated_at=? WHERE id=?",
            (state, stage, error, now(), identifier),
        )
        await self.emit(identifier)

    async def submit(self, spec: WorkflowCreate) -> WorkflowRun:
        canonical = spec.model_dump_json()
        async with self.lock:
            old = await self.store.one(
                "SELECT id,input_json FROM workflow_runs WHERE request_key=?", (spec.request_key,)
            )
            if old:
                if old["input_json"] != canonical:
                    raise AppError(
                        "request_conflict",
                        "This request key belongs to different workflow inputs.",
                        409,
                    )
                return await self.get(old["id"])
            if self.closing or len(self.tasks) >= 20:
                raise AppError("workflow_busy", "The workflow queue is full or shutting down.", 409)
            await self.runs.registry.resolve(spec.model.connection_id, spec.model.model_id)
            if spec.cleanup_model:
                await self.runs.registry.resolve(
                    spec.cleanup_model.connection_id, spec.cleanup_model.model_id
                )
            if spec.template == "meeting_pack":
                item = await attachments.attachment(self.store, str(spec.attachment_id))
                if item.kind != "audio":
                    raise AppError("unsupported_type", "Choose a recording for this workflow.", 422)
            elif not self.images.engine.status().available:
                raise AppError("image_unavailable", "The local image worker is unavailable.", 409)
            identifier, date = uuid4().hex, now()
            statements: list[tuple[str, tuple[object, ...]]] = [
                (
                    "INSERT INTO workflow_runs(id,request_key,input_json,state,stage,"
                    "created_at,updated_at) VALUES(?,?,?,'queued','Waiting for a step',?,?)",
                    (identifier, spec.request_key, canonical, date, date),
                )
            ]
            for position, (kind, label) in enumerate(
                templates.steps(spec.template, bool(spec.cleanup_model), len(spec.seeds))
            ):
                statements.append(
                    (
                        "INSERT INTO workflow_steps(run_id,position,kind,label) VALUES(?,?,?,?)",
                        (identifier, position, kind, label),
                    )
                )
            await self.store.batch(statements)
            await self.emit(identifier)
            self.schedule(identifier)
            return await self.get(identifier)

    def schedule(self, identifier: str) -> None:
        task = asyncio.create_task(self.execute(identifier), name="workflow-" + identifier)
        self.tasks[identifier] = task
        task.add_done_callback(lambda _: self.tasks.pop(identifier, None))

    async def save_step(
        self,
        identifier: str,
        step: WorkflowStep,
        state: str,
        output: dict[str, Any] | None,
        error: str | None = None,
    ) -> None:
        encoded = json.dumps(output) if output is not None else None
        await self.store.batch(
            [
                (
                    "UPDATE workflow_steps SET state=?,output_json=?,error=? "
                    "WHERE run_id=? AND position=?",
                    (state, encoded, error, identifier, step.position),
                ),
                (
                    "UPDATE workflow_attempts SET state=?,output_json=?,finished_at=? "
                    "WHERE run_id=? AND position=? AND attempt=?",
                    (
                        state,
                        encoded,
                        now() if state != "running" else None,
                        identifier,
                        step.position,
                        step.attempt,
                    ),
                ),
            ]
        )
        await self.emit(identifier)

    async def execute(self, identifier: str) -> None:
        current: WorkflowStep | None = None
        try:
            while True:
                run = await self.get(identifier)
                current = next((s for s in run.steps if s.state != "complete"), None)
                if current is None:
                    await self.state(identifier, "complete", "Ready for review")
                    return
                if current.state != "pending":
                    return
                draft = run.steps[0].output or {}
                needs_review = run.input.review_prompt or len(str(draft.get("text", ""))) > 4000
                if current.kind == "image" and needs_review and run.edited_prompt is None:
                    await self.state(identifier, "paused", "Review the image prompt")
                    return
                current.attempt += 1
                await self.store.batch(
                    [
                        (
                            "UPDATE workflow_steps SET state='running',attempt=?,error=NULL "
                            "WHERE run_id=? AND position=?",
                            (current.attempt, identifier, current.position),
                        ),
                        (
                            "INSERT INTO workflow_attempts(run_id,position,attempt,input_json,"
                            "state,started_at) VALUES(?,?,?,?,'running',?)",
                            (
                                identifier,
                                current.position,
                                current.attempt,
                                json.dumps(
                                    {
                                        "definition": run.input.model_dump(),
                                        "edited_prompt": run.edited_prompt,
                                        "prompt_version": templates.VERSION,
                                    }
                                ),
                                now(),
                            ),
                        ),
                    ]
                )
                await self.state(identifier, "running", current.label)
                output = await self.perform(run, current)
                await self.save_step(identifier, current, "complete", output)
        except asyncio.CancelledError:
            await self.stop_owned(identifier)
            if current and current.attempt:
                row = await self.store.one(
                    "SELECT state,output_json FROM workflow_steps WHERE run_id=? AND position=?",
                    (identifier, current.position),
                )
                cancel_output = (
                    json.loads(row["output_json"]) if row and row["output_json"] else None
                )
                if row and row["state"] == "running":
                    await self.save_step(
                        identifier,
                        current,
                        "interrupted" if self.closing else "cancelled",
                        cancel_output,
                    )
            await self.state(
                identifier,
                "interrupted" if self.closing else "cancelled",
                "Interrupted — retry available" if self.closing else "Cancelled",
            )
        except Exception as exc:
            error = (
                exc.message
                if isinstance(exc, AppError)
                else "This step failed. Earlier outputs are saved. Retry the failed step."
            )
            if current and current.attempt:
                row = await self.store.one(
                    "SELECT output_json FROM workflow_steps WHERE run_id=? AND position=?",
                    (identifier, current.position),
                )
                failed_output = (
                    json.loads(row["output_json"]) if row and row["output_json"] else None
                )
                await self.save_step(identifier, current, "failed", failed_output, error)
            await self.state(identifier, "failed", "Retry available", error)
        finally:
            await self.stop_owned(identifier)

    async def stop_owned(self, identifier: str) -> None:
        children = await self.store.rows(
            "SELECT id FROM image_jobs WHERE request_key LIKE ? "
            "AND state IN ('queued','preparing','running','cancelling')",
            (f"workflow-{identifier}-%",),
        )
        for child in children:
            await self.images.cancel(child["id"])
        self.owned_images.pop(identifier, None)
        job = self.owned_cleanup.pop(identifier, None)
        if job and not job.closed and job.task:
            job.task.cancel()
            await asyncio.gather(job.task, return_exceptions=True)

    async def known_image(self, identifier: str, step: WorkflowStep) -> ImageJob | None:
        image_id = step.output.get("image_job_id") if step.output else None
        if not image_id and step.attempt:
            row = await self.store.one(
                "SELECT id FROM image_jobs WHERE request_key=?",
                (f"workflow-{identifier}-{step.position}-{step.attempt}",),
            )
            image_id = row["id"] if row else None
            if image_id:
                step.output = {"image_job_id": image_id}
                await self.save_step(identifier, step, step.state, step.output)
        return await self.images.get(image_id) if image_id else None

    async def perform(self, run: WorkflowRun, step: WorkflowStep) -> dict[str, Any]:
        spec, identifier = run.input, run.id
        if step.kind == "transcribe":
            item = await attachments.attachment(self.store, str(spec.attachment_id))
            if not item.transcript or item.transcript.status != "ready":
                job = self.transcription.jobs.get(item.id)
                if job is None or job.closed:
                    await self.transcription.start(item.id)
                    job = self.transcription.jobs[item.id]
                if job.task:
                    await asyncio.shield(
                        job.task
                    )  # The attachment's transcription may also serve a chat.
            source = await attachments.transcript(self.store, item.id)
            if not source.attachment.transcript or source.attachment.transcript.status != "ready":
                raise AppError(
                    "transcript_failed",
                    "Transcription did not finish. Retry or choose a saved transcript.",
                    409,
                )
            original = {
                "attachment_id": item.id,
                "filename": item.filename,
                "text": source.text,
                "raw_text": source.raw_text,
                "segments": [s.model_dump() for s in source.segments],
                "cleaned_text": None,
            }
            await self.store.execute(
                "UPDATE workflow_runs SET source_json=? WHERE id=?",
                (json.dumps(original), identifier),
            )
            return {"text": "Original transcript saved", "attachment_id": item.id}
        if step.kind == "cleanup":
            assert spec.cleanup_model is not None
            acceptance = asyncio.create_task(
                self.cleanup.start(
                    str(spec.attachment_id),
                    spec.cleanup_model.connection_id,
                    spec.cleanup_model.model_id,
                )
            )
            try:
                await asyncio.shield(acceptance)
            except asyncio.CancelledError:
                # Finish acceptance so cancellation owns exactly the job we started.
                # Never cancel a pre-existing, independently started clean-up.
                outcome = await asyncio.gather(acceptance, return_exceptions=True)
                if not isinstance(outcome[0], BaseException):
                    self.owned_cleanup[identifier] = self.transcription.jobs[
                        str(spec.attachment_id)
                    ]
                raise
            job = self.transcription.jobs[str(spec.attachment_id)]
            self.owned_cleanup[identifier] = job
            if job.task:
                await asyncio.shield(job.task)
            value = await attachments.transcript(self.store, str(spec.attachment_id))
            if value.cleaned_text is None:
                raise AppError(
                    "cleanup_failed",
                    "Clean-up was rejected or interrupted. "
                    "Retry or continue with the original transcript.",
                    409,
                )
            row = await self.store.one(
                "SELECT source_json FROM workflow_runs WHERE id=?", (identifier,)
            )
            assert row
            source = json.loads(row["source_json"])
            if value.text != source["text"]:
                raise AppError(
                    "workflow_source_changed",
                    "This recording's transcript changed after the source was saved. "
                    "Continue with the saved original or start a new run.",
                    409,
                )
            source["cleaned_text"] = value.cleaned_text
            await self.store.execute(
                "UPDATE workflow_runs SET source_json=? WHERE id=?",
                (json.dumps(source), identifier),
            )
            return {"text": "Guarded clean-up saved; original transcript retained"}
        if step.kind == "image":
            draft = run.steps[0].output
            assert draft and "text" in draft
            prompt = run.edited_prompt or str(draft["text"])
            if not prompt.strip() or len(prompt) > 4000:
                raise AppError(
                    "workflow_prompt",
                    "Review and shorten the image prompt to 4,000 characters.",
                    409,
                )
            image = await self.known_image(identifier, step)
            if image is None or image.state in {"failed", "cancelled", "interrupted"}:
                image = await self.images.submit(
                    ImageCreate(
                        request_key=f"workflow-{identifier}-{step.position}-{step.attempt}",
                        prompt=prompt,
                        seed=spec.seeds[step.position - 1],
                        parent_id=None,
                    )
                )
            self.owned_images[identifier] = image.id
            await self.save_step(identifier, step, "running", {"image_job_id": image.id})
            task = self.images.tasks.get(image.id)
            if task:
                await asyncio.shield(task)
            image = await self.images.get(image.id)
            self.owned_images.pop(identifier, None)
            if image.state != "complete":
                raise AppError(
                    "workflow_image",
                    image.error or "Image generation did not finish. Retry this step.",
                    409,
                )
            return {"image_job_id": image.id, "sha256": image.sha256}
        if step.kind == "pack":
            connection = await self.store.one(
                "SELECT base_url FROM connections WHERE id=?", (spec.model.connection_id,)
            )
            host = urlsplit(str(connection["base_url"])).hostname if connection else None
            local = host == "localhost"
            try:
                local = local or bool(host and ip_address(host).is_loopback)
            except ValueError:
                pass
            if not local:
                raise AppError(
                    "recording_requires_local",
                    "Recording workflows need a local Ollama connection.",
                    422,
                )
            row = await self.store.one(
                "SELECT source_json FROM workflow_runs WHERE id=?", (identifier,)
            )
            assert row and row["source_json"]
            source = json.loads(row["source_json"])
            if not source["text"].strip():
                raise AppError(
                    "workflow_empty_source", "No speech is available for a meeting pack.", 409
                )
            material = (
                "<original_transcript>\n"
                + escape(timestamped(source["text"], source["segments"]))
                + "\n</original_transcript>"
            )
            if source.get("cleaned_text"):
                material += (
                    "\n<cleaned_reading_aid>\n"
                    + escape(source["cleaned_text"])
                    + "\n</cleaned_reading_aid>"
                )
            return await self.text(run, step, templates.MEETING_PACK, material)
        return await self.text(run, step, templates.IMAGE_PROMPT, spec.brief)

    async def text(
        self, run: WorkflowRun, step: WorkflowStep, system: str, material: str
    ) -> dict[str, Any]:
        selected = run.input.model
        model = await self.runs.registry.resolve(selected.connection_id, selected.model_id)
        params: dict[str, Any] = await self.runs.registry.params(
            model, selected.params.model_dump(exclude_none=True)
        )
        messages = [ProviderMessage("system", system), ProviderMessage("user", material)]
        pref = await self.store.one(
            "SELECT tokens_per_char FROM model_prefs WHERE connection_id=? AND model_id=?",
            (model.connection_id, model.model_id),
        )
        ratio = float(pref["tokens_per_char"] or 0.3) if pref else 0.3
        maximum = model.context_length or 8192
        reserve = int(params.get("max_tokens") or max(1024, min(8192, maximum * 0.25)))
        estimated = sum(int(len(m.content) * ratio) + 4 for m in messages)
        if estimated + reserve + 256 > maximum:
            raise AppError(
                "context_overflow",
                "The full source does not fit this model's input/output allowance. "
                "Choose a larger context or shorter source in a new run. No source was truncated.",
                422,
            )
        adapter = await self.runs.registry.adapter(model.connection_id)
        if adapter.capacity and adapter.capacity.busy:
            await self.state(run.id, "running", "Waiting for native capacity: " + step.label)
        request = ChatRequest(model.model_id, messages, params, maximum, params.get("reasoning"))
        await self.store.execute(
            "UPDATE workflow_attempts SET input_json=? WHERE run_id=? AND position=? AND attempt=?",
            (
                json.dumps(
                    {
                        "model": model.model_id,
                        "connection_id": model.connection_id,
                        "context_length": maximum,
                        "params": params,
                        "messages": [{"role": m.role, "content": m.content} for m in messages],
                        "prompt_version": templates.VERSION,
                    }
                ),
                run.id,
                step.position,
                step.attempt,
            ),
        )
        stream = adapter.stream(request, background=True)
        output: dict[str, Any] = {
            "text": "",
            "model": selected.model_dump(),
            "model_display_name": model.display_name,
            "resolved_params": params,
            "context_length": maximum,
            "prompt_version": templates.VERSION,
            "prompt_sha256": hashlib.sha256(system.encode()).hexdigest(),
            "draft": True,
        }
        last = 0.0
        finished = False
        try:
            async for event in stream:
                if isinstance(event, TextDelta):
                    if not output["text"]:
                        await self.state(run.id, "running", step.label)
                    output["text"] += event.text
                    clock = asyncio.get_running_loop().time()
                    if clock - last >= 1:
                        await self.save_step(run.id, step, "running", output)
                        last = clock
                elif isinstance(event, Finish):
                    if event.reason != "stop":
                        raise AppError(
                            "workflow_incomplete",
                            "The model did not finish this draft. "
                            "Partial output is saved; retry with your selected settings.",
                            409,
                        )
                    finished = True
            if not finished or not output["text"].strip():
                raise AppError(
                    "workflow_empty", "The model returned no complete draft. Retry this step.", 409
                )
            return output
        finally:
            await stream.aclose()
            if output["text"]:
                await self.save_step(run.id, step, "running", output)

    async def resume(self, identifier: str, body: WorkflowResume) -> WorkflowRun:
        async with self.lock:
            run = await self.get(identifier)
            if run.state in ACTIVE or identifier in self.tasks:
                raise AppError("workflow_busy", "This workflow is still running.", 409)
            if run.state == "complete":
                return run
            for prior in run.steps:
                if prior.kind == "image" and prior.state in {"failed", "interrupted", "cancelled"}:
                    image = await self.known_image(identifier, prior)
                    if image and image.state == "complete" and image.sha256:
                        await self.save_step(
                            identifier,
                            prior,
                            "complete",
                            {"image_job_id": image.id, "sha256": image.sha256},
                        )
            run = await self.get(identifier)
            if all(s.state == "complete" for s in run.steps):
                await self.state(identifier, "complete", "Ready for review")
                return await self.get(identifier)
            step = next(s for s in run.steps if s.state != "complete")
            if body.skip_cleanup:
                if step.kind != "cleanup":
                    raise AppError("workflow_step", "Only optional clean-up can be skipped.", 422)
                await self.save_step(
                    identifier,
                    step,
                    "complete",
                    {"text": "User chose the original transcript", "skipped": True},
                )
            elif step.kind == "image" and run.state == "paused":
                draft = run.steps[0].output
                assert draft
                prompt = body.prompt if body.prompt is not None else str(draft["text"])
                if not prompt.strip() or len(prompt) > 4000:
                    raise AppError(
                        "workflow_prompt", "Use an image prompt of 1–4,000 characters.", 422
                    )
                await self.store.execute(
                    "UPDATE workflow_runs SET edited_prompt=? WHERE id=?", (prompt, identifier)
                )
            else:
                await self.store.execute(
                    "UPDATE workflow_steps SET state='pending',error=NULL "
                    "WHERE run_id=? AND state IN ('failed','interrupted','cancelled')",
                    (identifier,),
                )
            await self.state(identifier, "queued", "Waiting for a step")
            self.schedule(identifier)
            return await self.get(identifier)

    async def cancel(self, identifier: str) -> WorkflowRun:
        async with self.lock:
            run = await self.get(identifier)
            task = self.tasks.get(identifier)
            if run.state in ACTIVE and task:
                await self.state(identifier, "cancelling", "Stopping current step")
                task.cancel()
            elif run.state == "paused":
                await self.store.execute(
                    "UPDATE workflow_steps SET state='cancelled' "
                    "WHERE run_id=? AND state='pending'",
                    (identifier,),
                )
                await self.state(identifier, "cancelled", "Cancelled")
        if task:
            await task
        return await self.get(identifier)

    async def recover(self) -> None:
        await self.store.execute(
            "UPDATE workflow_steps SET state='interrupted' WHERE state='running'"
        )
        await self.store.execute(
            "UPDATE workflow_attempts SET state='interrupted',finished_at=? WHERE state='running'",
            (now(),),
        )
        for row in await self.store.rows(
            "SELECT id,state FROM workflow_runs WHERE state IN ('queued','running','cancelling')"
        ):
            # Reconcile a committed image that finished before the workflow commit.
            run = await self.get(row["id"])
            for step in run.steps:
                if step.state == "interrupted" and step.kind == "image":
                    job = await self.known_image(run.id, step)
                    if job and job.state == "complete":
                        await self.save_step(
                            run.id, step, "complete", {"image_job_id": job.id, "sha256": job.sha256}
                        )
            recovered = await self.get(row["id"])
            if all(s.state == "complete" for s in recovered.steps):
                await self.state(row["id"], "complete", "Ready for review")
            elif row["state"] == "queued" and all(
                s.state in {"complete", "pending"} for s in recovered.steps
            ):
                self.schedule(row["id"])
            else:
                await self.state(row["id"], "interrupted", "Interrupted — retry available")

    async def tail(self, after: int) -> AsyncIterator[tuple[int, str, dict[str, Any]]]:
        async with self.changed:
            latest = await self.store.one("SELECT COALESCE(MAX(id),0) n FROM workflow_events")
            sequence = int(latest["n"]) if latest else 0
            replay = (
                await self.store.rows(
                    "SELECT id,data_json FROM workflow_events WHERE id>? AND id<=? ORDER BY id",
                    (after, sequence),
                )
                if 0 < after <= sequence
                else []
            )
            snapshot = {"runs": [r.model_dump() for r in await self.list()]}
        for record in replay:
            yield record["id"], "workflow.updated", {"run": json.loads(record["data_json"])}
        yield sequence, "workflow.snapshot", snapshot
        after = sequence
        while True:
            async with self.changed:
                records = await self.store.rows(
                    "SELECT id,data_json FROM workflow_events WHERE id>? ORDER BY id", (after,)
                )
                while not records:
                    await self.changed.wait()
                    records = await self.store.rows(
                        "SELECT id,data_json FROM workflow_events WHERE id>? ORDER BY id", (after,)
                    )
            for record in records:
                after = record["id"]
                yield after, "workflow.updated", {"run": json.loads(record["data_json"])}

    async def close(self) -> None:
        self.closing = True
        tasks = list(self.tasks.values())
        for task in tasks:
            task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
